sections=[]
for i,s in enumerate(slides):
    kicker=f'<div class="eyebrow">{s["kicker"]}</div>'
    title='<h1>'+s['title'].replace('\n','<br>')+'</h1>'
    lead=f'<p class="lead">{s["lead"]}</p>'
    body='<p class="body-copy">'+s.get('body','').replace('\n','<br>')+'</p>'
    outcome=f'<div class="outcome">{s["outcome"]}</div>' if s.get('outcome') else ''
    if s.get('type')=='flow':
        content=f'<div class="flow-head">{kicker}{title}{lead}</div><ol class="flow">'+''.join(f'<li><span>{n}</span><h2>{t}</h2><p>{d}</p></li>' for n,t,d in s['steps'])+'</ol><p class="flow-foot">记录连着画面，提醒跟着安排。每件事都能查看，也都能回应。</p>'
    elif s.get('type')=='end':
        content=f'<div class="end-copy">{kicker}{title}{lead}{body}<a class="open-demo" href="在家InHome_iOS_Demo.html">体验在家 ↗</a></div><div class="end-right"><div class="big-word">在家<span>INHOME</span></div><div class="capability"><p><b>随时看家</b>画面与家的记录，随手可看</p><p><b>重要提醒</b>轻点消息，了解发生经过</p><p><b>生活帮手</b>发现扩展，也分享你的点子</p></div></div>'
    else:
        modes='<div class="mode-comparison"><div><b>高效</b><span>专注重要的事情</span></div><div><b>陪伴</b><span>偶尔分享家中日常</span></div></div>' if s.get('type')=='modes' else ''
        content=f'<div class="copy">{kicker}{title}{lead}{body}{modes}{outcome}</div><figure class="visual"><div class="screenshot"><img src="{picture(s["image"],s.get("crop"))}" alt="{s["caption"]}"></div><figcaption>{s["caption"]}</figcaption></figure>'
    sections.append(f'<section class="slide {s.get("type", "scene")}" aria-label="第 {i+1} 页：{s["title"].replace(chr(10),"")}" data-duration="{s["seconds"]}" {"" if i==0 else "hidden"}>{content}</section>')

